Below is a complete Arduino sketch that reads a PDM microphone (using the Arduino PDM library) and detects a loud, sustained noise by computing the short-term RMS level and requiring it to stay above a threshold for a configured duration. Notes: this requires a board with PDM support (for example Arduino Nano 33 BLE Sense or other SAMD-based boards with a PDM microphone). Tune the threshold, buffer size and sustained duration to match your microphone and environment.

```cpp
#include <PDM.h>

// Configurable parameters
const unsigned int SAMPLE_RATE = 16000;      // Hz (typical values: 8000, 16000)
const unsigned int BUFFER_SAMPLES = 256;     // samples per PDM callback (power of two helps)
const float THRESHOLD = 0.12;                // normalized RMS threshold (0..1). Tune this.
const unsigned long SUSTAIN_MS = 500;        // required continuous time above threshold to trigger (ms)
const int LED_PIN = LED_BUILTIN;             // indicator LED

// Buffer to receive PCM samples (16-bit signed)
static int16_t pdmBuffer[BUFFER_SAMPLES];
volatile int samplesAvailable = 0;            // number of samples placed in buffer
volatile bool dataReady = false;             // flag set by PDM callback

// Tracking sustained loudness
unsigned long loudStart = 0;
bool alarmTriggered = false;

// PDM receive callback runs when a chunk of PCM is available
void onPDMdata() {
  // Read available PCM samples (PDM.read returns bytes)
  int bytes = PDM.read(pdmBuffer, BUFFER_SAMPLES * sizeof(int16_t));
  if (bytes > 0) {
    samplesAvailable = bytes / sizeof(int16_t);
    dataReady = true; // signal main loop to process
  }
}

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 2000) ;

  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  // Start PDM (1 = mono). Some boards default to 1 channel.
  if (!PDM.begin(1, SAMPLE_RATE)) {
    Serial.println("Failed to start PDM microphone");
    while (1) delay(1000);
  }
  PDM.onReceive(onPDMdata);

  Serial.println("PDM microphone started");
}

void loop() {
  if (dataReady) {
    // copy local to avoid race with ISR
    noInterrupts();
    int localSamples = samplesAvailable;
    dataReady = false;
    interrupts();

    if (localSamples > 0) {
      // Compute RMS of the buffer
      unsigned long sumSquares = 0;
      for (int i = 0; i < localSamples; ++i) {
        int32_t s = pdmBuffer[i];
        sumSquares += (uint32_t)(s * (int32_t)s);
      }
      float meanSquare = (float)sumSquares / (float)localSamples;
      float rms = sqrt(meanSquare) / 32768.0; // normalize (approx range 0..1)

      // Debug print (comment out for performance)
      // Serial.print("RMS="); Serial.println(rms, 4);

      // Check sustained loudness
      unsigned long now = millis();
      if (rms >= THRESHOLD) {
        if (loudStart == 0) loudStart = now; // begin count
        unsigned long duration = now - loudStart;
        if (duration >= SUSTAIN_MS && !alarmTriggered) {
          alarmTriggered = true;
          onLoudSustainedDetected();
        }
      } else {
        // below threshold -> reset
        loudStart = 0;
        alarmTriggered = false; // allow new detection after it falls below
      }
    }
  }
  // Do other tasks here
}

void onLoudSustainedDetected() {
  Serial.println("Loud sustained noise detected!");
  // Indicator: blink LED
  for (int i = 0; i < 3; ++i) {
    digitalWrite(LED_PIN, HIGH);
    delay(100);
    digitalWrite(LED_PIN, LOW);
    delay(100);
  }
}
```

Tuning tips:
- THRESHOLD: start around 0.08–0.18 and adjust. Lower makes detection more sensitive; increase to avoid false triggers.
- BUFFER_SAMPLES and SAMPLE_RATE affect time resolution and RMS stability. Larger buffers give smoother RMS but slower responsiveness.
- SUSTAIN_MS controls how long the sound must persist to count as sustained. Increase to avoid short loud pops being detected.

