    Display display = new Display();
    Shell shell = new Shell(display);
    shell.setText("Searchable List");
    shell.setSize(400, 300);
    shell.setLayout(new GridLayout(1, false));

    Label lbl = new Label(shell, SWT.NONE);
    lbl.setText("Filter:");

    Text filterText = new Text(shell, SWT.BORDER | SWT.SEARCH | SWT.ICON_SEARCH | SWT.CANCEL);
    filterText.setLayoutData(new GridData(GridData.FILL_HORIZONTAL));

    final List list = new List(shell, SWT.BORDER | SWT.V_SCROLL | SWT.H_SCROLL);
    list.setLayoutData(new GridData(GridData.FILL_BOTH));

    final String[] items = new String[] {
      "Apple", "Banana", "Cherry", "Date", "Elderberry", "Fig",
      "Grape", "Honeydew", "Kiwi", "Lemon", "Mango", "Orange",
      "Papaya", "Quince", "Raspberry", "Strawberry", "Tomato", "Ugli fruit", "Watermelon"
    };

    list.setItems(items);

    filterText.addModifyListener(new ModifyListener() {
      public void modifyText(ModifyEvent e) {
        String pattern = filterText.getText().toLowerCase();
        if (pattern.isEmpty()) {
          list.setItems(items);
          return;
        }
        java.util.List<String> filtered = new java.util.ArrayList<>();
        for (String it : items) {
          if (it.toLowerCase().contains(pattern)) {
            filtered.add(it);
          }
        }
        list.setItems(filtered.toArray(new String[0]));
      }
    });

    shell.open();
    while (!shell.isDisposed()) {
      if (!display.readAndDispatch()) display.sleep();
    }
    display.dispose();
  }
}
