// Function to calculate the wavelet coefficients using DWT
void wavelet_coefficients(Wavelet *wave, float *input, float *coeffs, int len) {
    WaveletChild *child = wave->child;
    int i, j;

    // Calculate the wavelet coefficients for each window
    for (i = 0; i < len; i++) {
        // Down-sample the input signal by a factor of 2
        float temp = input[i];
        input[i] = input[i + len / 2];
        wave->value = temp;

