// CommandLine.h
// Single-file Arduino command-line interpreter (header-only)
// - Register commands with an arbitrary number of parameters
// - Reads from a Stream (Serial by default)
// - Simple tokenization supporting quoted strings and escapes
// Usage example:
//   #include "CommandLine.h"
//   CommandLine cli(Serial);
//   void cmd_echo(int argc, char **argv) { for (int i=1;i<argc;i++){ Serial.print(argv[i]); if(i+1<argc) Serial.print(' ');} Serial.println(); }
//   void setup(){ Serial.begin(115200); cli.addCommand("echo", cmd_echo, "echo args"); }
//   void loop(){ cli.poll(); }

#ifndef COMMANDLINE_H
#define COMMANDLINE_H

#include <Arduino.h>

class CommandLine {
public:
  typedef void (*CmdFunc)(int argc, char **argv);

  // Defaults can be overridden before including header
#ifndef CLI_INPUT_BUFFER_SIZE
#define CLI_INPUT_BUFFER_SIZE 192
#endif
#ifndef CLI_MAX_COMMANDS
#define CLI_MAX_COMMANDS 24
#endif
#ifndef CLI_MAX_ARGS
#define CLI_MAX_ARGS 16
#endif

  CommandLine(Stream &io = Serial)
    : _io(&io), _bufPos(0), _cmdCount(0)
  {
    _inputBuf[0] = '\0';
    // register built-in help command
    addCommand("help", [](int argc, char **argv){ /* placeholder, bound below */ }, "show help");
    // replace help placeholder with bound method that has access to this pointer
    // We'll fix the function pointer to call the instance method when help is invoked.
    // Achieved by storing a pointer to a static trampoline that recovers the instance from a global slot.
    _helpIndex = 0; // index 0 is help by default
    s_lastInstance = this;
    // set the real help handler
    _commands[_helpIndex].func = &CommandLine::helpTrampoline;
  }

  // Register a command. Returns false if table full or name already exists.
  bool addCommand(const char *name, CmdFunc func, const char *help = nullptr) {
    if (_cmdCount >= CLI_MAX_COMMANDS) return false;
    // avoid duplicates
    for (int i = 0; i < _cmdCount; ++i) {
      if (strcmp(_commands[i].name, name) == 0) return false;
    }
    _commands[_cmdCount].name = name;
    _commands[_cmdCount].func = func;
    _commands[_cmdCount].help = help;
    ++_cmdCount;
    return true;
  }

  // Call regularly from loop()
  void poll() {
    while (_io->available()) {
      int c = _io->read();
      if (c < 0) break;
      if (c == '\r') continue; // ignore CR
      if (c == '\n') {
        if (_bufPos > 0) {
          _inputBuf[_bufPos] = '\0';
          processLine(_inputBuf);
          _bufPos = 0;
        }
      } else {
        if (_bufPos < (CLI_INPUT_BUFFER_SIZE - 1)) {
          _inputBuf[_bufPos++] = (char)c;
        } // else: discard extra
      }
    }
  }

  // Process a line of input immediately
  void processLine(const char *line) {
    // copy into mutable buffer
    char tmp[CLI_INPUT_BUFFER_SIZE];
    strncpy(tmp, line, CLI_INPUT_BUFFER_SIZE - 1);
    tmp[CLI_INPUT_BUFFER_SIZE - 1] = '\0';

    // tokenize in-place
    char *argv[CLI_MAX_ARGS];
    int argc = tokenize(tmp, argv, CLI_MAX_ARGS);
    if (argc <= 0) return;

    // find command
    for (int i = 0; i < _cmdCount; ++i) {
      if (strcmp(argv[0], _commands[i].name) == 0) {
        CmdFunc f = _commands[i].func;
        if (f) {
          f(argc, argv);
        }
        return;
      }
    }
    _io->print("Unknown command: ");
    _io->println(argv[0]);
  }

  // Convenience helpers
  static long toInt(const char *s, long def = 0) {
    if (!s) return def;
    char *endptr;
    long v = strtol(s, &endptr, 0);
    if (endptr == s) return def;
    return v;
  }
  static double toFloat(const char *s, double def = 0.0) {
    if (!s) return def;
    char *endptr;
    double v = strtod(s, &endptr);
    if (endptr == s) return def;
    return v;
  }

private:
  struct CommandEntry { const char *name; CmdFunc func; const char *help; };

  Stream *_io;
  char _inputBuf[CLI_INPUT_BUFFER_SIZE];
  size_t _bufPos;
  CommandEntry _commands[CLI_MAX_COMMANDS];
  int _cmdCount;
  int _helpIndex;

  // Tokenizer: supports quoted strings (") and backslash escapes. Returns argc, argv is filled.
  int tokenize(char *s, char **argv, int maxArgs) {
    int argc = 0;
    char *p = s;
    while (*p && argc < maxArgs) {
      // skip whitespace
      while (*p && isSpace(*p)) ++p;
      if (!*p) break;
      if (*p == '"') {
        // quoted
        ++p; // skip quote
        argv[argc++] = p;
        while (*p && *p != '"') {
          if (*p == '\\' && *(p+1)) {
            // shift left the escaped char
            char esc = *(p+1);
            *p = esc;
            memmove(p+1, p+2, strlen(p+2)+1);
          } else {
            ++p;
          }
        }
        if (*p == '"') {
          *p++ = '\0';
        }
      } else {
        argv[argc++] = p;
        while (*p && !isSpace(*p)) {
          if (*p == '\\' && *(p+1)) {
            char esc = *(p+1);
            *p = esc;
            memmove(p+1, p+2, strlen(p+2)+1);
          } else {
            ++p;
          }
        }
        if (*p) *p++ = '\0';
      }
    }
    // ensure argv[argc] == NULL for convenience
    if (argc < maxArgs) argv[argc] = NULL;
    return argc;
  }

  static inline bool isSpace(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }

  // help handler: instance method
  void printHelp(int argc, char **argv) {
    (void)argc; (void)argv;
    _io->println("Available commands:");
    for (int i = 0; i < _cmdCount; ++i) {
      _io->print("  "); _io->print(_commands[i].name);
      if (_commands[i].help) { _io->print(" - "); _io->print(_commands[i].help); }
      _io->println();
    }
  }

  // static trampoline so help command (which is a simple function pointer) can call the instance method
  static void helpTrampoline(int argc, char **argv) {
    if (s_lastInstance) s_lastInstance->printHelp(argc, argv);
  }

  // keep pointer to the last constructed instance so the built-in help works
  static CommandLine *s_lastInstance;
};

// define static instance pointer
CommandLine *CommandLine::s_lastInstance = nullptr;

#endif // COMMANDLINE_H

