int main(void) {
    const char *reponses[] = {
        "C'est certain.",
        "Sans aucun doute.",
        "Oui — définitivement.",
        "Très probable.",
        "Oui.",
        "Les signes pointent vers oui.",
        "Réponse floue, essaie encore.",
