        "Peu probable.",
        "C'est possible.",
        "Concentre-toi et reviens poser la question.",
        "Les probabilités sont en ta faveur.",
        "Pas dans un avenir proche.",
        "Tout indique oui."
    };

    const int n = sizeof(reponses) / sizeof(reponses[0]);
    char question[256];

    srand((unsigned)time(NULL));

    printf("Ask the 8-Ball (laissez la ligne vide et appuyez sur Entrée pour quitter)\n");
    while (1) {
        printf("\nPosez votre question : ");
        if (!fgets(question, sizeof(question), stdin)) break; // EOF
        // retirer le \n final
        size_t len = strlen(question);
        if (len > 0 && question[len - 1] == '\n') question[len - 1] = '\0';
        if (strlen(question) == 0) break; // quitter si ligne vide

        int idx = rand() % n;
        printf("La boule magique dit : %s\n", reponses[idx]);
    }

    printf("Au revoir !\n");
    return 0;
}

Notes courtes :
- Le programme boucle jusqu'à ce que l'utilisateur entre une ligne vide.
- Les réponses sont choisies aléatoirement via rand(); pour une meilleure randomness en usage critique, utilisez un générateur plus robuste.
