import java.time.LocalDate;
import java.time.LocalTime;
import java.time.Duration;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class CalendarEvent {
    private final String title;
    private final LocalDate date;
    private final LocalTime startTime;
    private final Duration duration;

    public CalendarEvent(String title, LocalDate date, LocalTime startTime, Duration duration) {
        if (title == null || date == null || startTime == null || duration == null) {
            throw new NullPointerException("Fields must not be null");
        }
        if (duration.isNegative() || duration.isZero()) {
            throw new IllegalArgumentException("Duration must be positive");
        }
        this.title = title;
        this.date = date;
        this.startTime = startTime;
        this.duration = duration;
    }

    public String getTitle() { return title; }
    public LocalDate getDate() { return date; }
    public LocalTime getStartTime() { return startTime; }
    public Duration getDuration() { return duration; }

    public LocalTime getEndTime() {
        return startTime.plus(duration);
    }

    @Override
    public String toString() {
        DateTimeFormatter dateFmt = DateTimeFormatter.ISO_LOCAL_DATE;
        DateTimeFormatter timeFmt = DateTimeFormatter.ofPattern("HH:mm");
        return String.format("%s — %s %s (%s)",
                title,
                date.format(dateFmt),
                startTime.format(timeFmt),
                formatDuration(duration));
    }

    private static String formatDuration(Duration d) {
        long hours = d.toHours();
        long minutes = d.minusHours(hours).toMinutes();
        if (hours > 0 && minutes > 0) return String.format("%dh %02dm", hours, minutes);
        if (hours > 0) return String.format("%dh", hours);
        return String.format("%dm", minutes);
    }
}

// Small program that creates a list of CalendarEvents and prints them
public class CalendarApp {
    public static void main(String[] args) {
        List<CalendarEvent> events = new ArrayList<>();

        events.add(new CalendarEvent("Team Meeting",
                LocalDate.of(2026, 1, 5),
                LocalTime.of(9, 0),
                Duration.ofMinutes(60)));

        events.add(new CalendarEvent("Lunch with Sarah",
                LocalDate.of(2026, 1, 5),
                LocalTime.of(12, 30),
                Duration.ofMinutes(90)));

        events.add(new CalendarEvent("Dentist",
                LocalDate.of(2026, 1, 6),
                LocalTime.of(15, 0),
                Duration.ofMinutes(30)));

        // Print events
        for (CalendarEvent e : events) {
            System.out.println(e);
        }
    }
}

Notes:
- Uses LocalDate, LocalTime, and Duration for robust date/time handling.
- toString prints a compact human-readable representation.
- You can extend this with sorting, filtering, or persistence as needed.

