package main

import (
    "fmt"
    "hash/crc32"
    "sort"
    "strconv"
    "sync"
)

type HashRing struct {
    replicas int
    keys     []uint32          // sorted
    hashMap  map[uint32]string // maps vnode hash -> node
    mu       sync.RWMutex
}

// New creates a hash ring with the given number of virtual node replicas
// and optional initial nodes.
func New(replicas int, nodes ...string) *HashRing {
    hr := &HashRing{
        replicas: replicas,
        hashMap:  make(map[uint32]string),
    }
    hr.Add(nodes...)
    return hr
}

func (hr *HashRing) hashKey(key string) uint32 {
    return crc32.ChecksumIEEE([]byte(key))
}

// Add adds one or more physical nodes to the ring, creating 'replicas'
// virtual nodes for each.
func (hr *HashRing) Add(nodes ...string) {
    hr.mu.Lock()
    defer hr.mu.Unlock()
    for _, node := range nodes {
        for i := 0; i < hr.replicas; i++ {
            vnode := node + "#" + strconv.Itoa(i)
            h := hr.hashKey(vnode)
            hr.keys = append(hr.keys, h)
            hr.hashMap[h] = node
        }
    }
    sort.Slice(hr.keys, func(i, j int) bool { return hr.keys[i] < hr.keys[j] })
}

// Remove removes a physical node and all its virtual nodes from the ring.
func (hr *HashRing) Remove(node string) {
    hr.mu.Lock()
    defer hr.mu.Unlock()
    for i := 0; i < hr.replicas; i++ {
        vnode := node + "#" + strconv.Itoa(i)
        h := hr.hashKey(vnode)
        delete(hr.hashMap, h)
        // remove h from keys slice (keys is sorted)
        idx := sort.Search(len(hr.keys), func(i int) bool { return hr.keys[i] >= h })
        if idx < len(hr.keys) && hr.keys[idx] == h {
            hr.keys = append(hr.keys[:idx], hr.keys[idx+1:]...)
        }
    }
}

// Get returns the node responsible for the given key. The bool is false
// when the ring is empty.
func (hr *HashRing) Get(key string) (string, bool) {
    hr.mu.RLock()
    defer hr.mu.RUnlock()
    if len(hr.keys) == 0 {
        return "", false
    }
    h := hr.hashKey(key)
    idx := sort.Search(len(hr.keys), func(i int) bool { return hr.keys[i] >= h })
    if idx == len(hr.keys) {
        idx = 0
    }
    node := hr.hashMap[hr.keys[idx]]
    return node, true
}

func main() {
    ring := New(3, "nodeA", "nodeB", "nodeC")

    keys := []string{"alpha", "beta", "gamma", "delta"}
    for _, k := range keys {
        if node, ok := ring.Get(k); ok {
            fmt.Printf("%s => %s\n", k, node)
        }
    }

    // Add a node and show remapping
    ring.Add("nodeD")
    fmt.Println("After adding nodeD:")
    for _, k := range keys {
        if node, ok := ring.Get(k); ok {
            fmt.Printf("%s => %s\n", k, node)
        }
    }

    // Remove a node
    ring.Remove("nodeB")
    fmt.Println("After removing nodeB:")
    for _, k := range keys {
        if node, ok := ring.Get(k); ok {
            fmt.Printf("%s => %s\n", k, node)
        }
    }
}

