Here's a concise TypeScript implementation that matches the tests you provided:

function parsePath(path: string): Array<string | number | null> {
  const result: Array<string | number | null> = [];
  let i = 0;
  const n = path.length;

  while (i < n) {
    // skip dot separators
    if (path[i] === '.') { i++; continue; }

    // bracket notation
    if (path[i] === '[') {
      const end = path.indexOf(']', i + 1);
      const inner = end === -1 ? path.slice(i + 1) : path.slice(i + 1, end);

      if (inner === '') {
        result.push(null);
      } else if (/^\d+$/.test(inner)) {
        result.push(Number(inner));
      } else {
        result.push(inner);
      }

      i = end === -1 ? n : end + 1;
      continue;
    }

    // dot/identifier segment
    const start = i;
    while (i < n && path[i] !== '.' && path[i] !== '[') i++;
    const token = path.slice(start, i);
    if (token.length) result.push(token);
  }

  return result;
}

This function returns an array of strings, numbers, or null and handles mixed dot and bracket notation, empty paths, empty brackets (as null), numeric bracket indices (as numbers), and identifier bracket contents (as strings).

